window.NPT.money = n => "₹" + Number(n).toLocaleString("en-IN");
window.NPT.load = () => {
  try { return JSON.parse(localStorage.getItem(window.NPT.storageKey)) || {products:window.NPT.products, orders:[], customers:[], notifications:[], banners:[]}; }
  catch(e) { return {products:window.NPT.products, orders:[], customers:[], notifications:[], banners:[]}; }
};
window.NPT.save = s => localStorage.setItem(window.NPT.storageKey, JSON.stringify(s));
window.NPT.productImage = (p) => (p.image && String(p.image).trim()) ? p.image : window.NPT.productArt(p);
window.NPT.stars = (rating) => {
  const r = Math.round(Number(rating || 0) * 2) / 2;
  let s = '';
  for (let i = 1; i <= 5; i++) s += i <= r ? '★' : (i - 0.5 === r ? '⯪' : '☆');
  return s;
};
window.NPT.categoryArt = (name, i=0) => {
  const palette = ['#0c2b4f','#12385d','#0b2037','#173b5c','#0e2f52','#1a4468'];
  const accent = palette[i % palette.length];
  const shapes = [
    `<circle cx="200" cy="90" r="60" fill="#ffffff14"/><rect x="60" y="120" width="220" height="55" rx="22" fill="#ffffff22"/>`,
    `<rect x="90" y="40" width="40" height="160" rx="16" fill="#ffffff20"/><circle cx="220" cy="120" r="46" fill="#ffffff16"/>`,
    `<polygon points="220,30 260,170 60,170" fill="#ffffff16"/>`,
    `<rect x="60" y="70" width="220" height="30" rx="14" fill="#ffffff1c"/><rect x="60" y="120" width="150" height="30" rx="14" fill="#ffffff14"/>`,
  ];
  const shape = shapes[i % shapes.length];
  const safe = String(name).replace(/&/g,'and');
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="360" height="220" viewBox="0 0 360 220">
  <defs><linearGradient id="g${i}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${accent}"/><stop offset="1" stop-color="#050d18"/></linearGradient></defs>
  <rect width="360" height="220" fill="url(#g${i})"/>
  <g transform="translate(20 10)">${shape}</g>
  <circle cx="330" cy="20" r="70" fill="#ffc90012"/>
</svg>`)}`;
};
window.NPT.productArt = (p) => {
  const brandColor = p.brand === 'Makita' ? '#0f8f6f' : '#0c2b4f';
  const dark = p.brand === 'Makita' ? '#0a4a3a' : '#0a1c33';
  const cat = (p.category||'').toLowerCase();
  let body;
  if (cat.includes('grind')) {
    body = `<g transform="translate(150 150) rotate(-8)">
      <rect x="0" y="30" width="230" height="80" rx="36" fill="${brandColor}"/>
      <rect x="-50" y="45" width="80" height="55" rx="22" fill="${dark}"/>
      <circle cx="255" cy="70" r="52" fill="${dark}"/><circle cx="255" cy="70" r="30" fill="#c7cdd4"/>
      <rect x="55" y="4" width="70" height="30" rx="10" fill="#ffc900"/>
    </g>`;
  } else if (cat.includes('rotary') || cat.includes('demolition')) {
    body = `<g transform="translate(160 60)">
      <rect x="20" y="0" width="70" height="220" rx="24" fill="${brandColor}"/>
      <rect x="-10" y="70" width="120" height="60" rx="24" fill="${dark}"/>
      <rect x="35" y="215" width="40" height="70" rx="14" fill="#20242c"/>
      <rect x="35" y="-20" width="40" height="30" rx="10" fill="#ffc900"/>
    </g>`;
  } else if (cat.includes('drill')) {
    body = `<g transform="translate(140 140) rotate(-14)">
      <rect x="0" y="20" width="230" height="65" rx="30" fill="${brandColor}"/>
      <rect x="60" y="80" width="45" height="120" rx="18" fill="${dark}"/>
      <rect x="215" y="30" width="80" height="46" rx="14" fill="#20242c"/>
      <circle cx="30" cy="52" r="26" fill="#c7cdd4"/>
    </g>`;
  } else if (cat.includes('cut') || cat.includes('saw')) {
    body = `<g transform="translate(130 90)">
      <rect x="0" y="60" width="220" height="60" rx="26" fill="${brandColor}"/>
      <path d="M210 30 A70 70 0 0 1 210 170 L150 100 Z" fill="#c7cdd4"/>
      <rect x="10" y="150" width="70" height="70" rx="16" fill="${dark}"/>
    </g>`;
  } else if (cat.includes('measur')) {
    body = `<g transform="translate(150 90)">
      <rect x="0" y="0" width="180" height="90" rx="20" fill="${brandColor}"/>
      <rect x="20" y="20" width="140" height="16" rx="8" fill="#ffffffaa"/>
      <rect x="20" y="50" width="90" height="16" rx="8" fill="#ffffff66"/>
    </g>`;
  } else if (cat.includes('garden')) {
    body = `<g transform="translate(120 40)">
      <rect x="90" y="0" width="26" height="220" rx="12" fill="${dark}"/>
      <rect x="40" y="180" width="140" height="60" rx="22" fill="${brandColor}"/>
      <circle cx="103" cy="12" r="18" fill="#ffc900"/>
    </g>`;
  } else {
    body = `<g transform="translate(140 130) rotate(-10)">
      <rect x="0" y="0" width="250" height="90" rx="36" fill="${brandColor}"/>
      <rect x="-40" y="15" width="80" height="60" rx="24" fill="${dark}"/>
      <circle cx="220" cy="45" r="40" fill="${dark}"/><circle cx="220" cy="45" r="22" fill="#c7cdd4"/>
      <rect x="60" y="-24" width="70" height="30" rx="10" fill="#ffc900"/>
    </g>`;
  }
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="700" height="520" viewBox="0 0 700 520">
  <defs><radialGradient id="bg" cx="50%" cy="38%" r="75%"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#eef1f4"/></radialGradient></defs>
  <rect width="700" height="520" rx="36" fill="url(#bg)"/>
  <ellipse cx="350" cy="440" rx="230" ry="26" fill="#00000010"/>
  ${body}
  <text x="36" y="486" font-family="Arial" font-size="14" font-weight="800" letter-spacing="1.5" fill="${brandColor}">${(p.brand||'').toUpperCase()}</text>
</svg>`)}`;
};
